def check_s0(k, m, limit):
    # Check if k*11 + m*20 <= limit
    return k * 11 + m * 20 <= limit

limit = 50
elements = set()
for k in range(10):
    for m in range(5):
        if check_s0(k, m, limit):
            elements.add(k * 11 + m * 20)

print(f"Elements in S0 up to {limit}: {sorted(list(elements))}")
